mapper.select:
SELECT id, workspace_id, doc_id, user_id, content, quote_text, created_at, updated_at
FROM req_doc_comment
WHERE id = #{id}

mapper.delete:
DELETE FROM req_doc_comment
WHERE workspace_id = #{workspaceId}
  AND doc_id IN (SELECT id FROM requirement_doc WHERE workspace_id = #{workspaceId} AND req_id = #{reqId})
